#include <stdio.h>
#include <stdlib.h>

#define BUF_SIZE (1 << 16)

static unsigned char inbuf[BUF_SIZE];
static size_t inpos = 0, inlen = 0;

static int readChar(void) {
    if (inpos == inlen) {
        inlen = fread(inbuf, 1, BUF_SIZE, stdin);
        inpos = 0;
        if (inlen == 0) return EOF;
    }
    return inbuf[inpos++];
}

static int readInt(void) {
    int c;
    do {
        c = readChar();
    } while (c <= ' ' && c != EOF);

    int value = 0;
    while (c >= '0' && c <= '9') {
        value = value * 10 + (c - '0');
        c = readChar();
    }
    return value;
}

static char readTokenChar(void) {
    int c;
    do {
        c = readChar();
    } while (c <= ' ' && c != EOF);
    return (char)c;
}

static char outbuf[BUF_SIZE];
static size_t outpos = 0;

static void flushOutput(void) {
    fwrite(outbuf, 1, outpos, stdout);
    outpos = 0;
}

static void writeChar(char c) {
    if (outpos == BUF_SIZE) flushOutput();
    outbuf[outpos++] = c;
}

static void writeInt(int value) {
    char digits[12];
    int count = 0;

    do {
        digits[count++] = (char)('0' + value % 10);
        value /= 10;
    } while (value > 0);

    while (count > 0) writeChar(digits[--count]);
}

int main(void) {
    int N = readInt();
    int M = readInt();
    int P = readInt();

    int *rows = malloc((size_t)N * sizeof(int));
    int *cols = malloc((size_t)M * sizeof(int));

    for (int i = 0; i < N; i++) rows[i] = i;
    for (int j = 0; j < M; j++) cols[j] = j;

    for (int i = 0; i < P; i++) {
        char op = readTokenChar();
        int a = readInt() - 1;
        int b = readInt() - 1;

        if (op == 'L') {
            int tmp = rows[a];
            rows[a] = rows[b];
            rows[b] = tmp;
        } else {
            int tmp = cols[a];
            cols[a] = cols[b];
            cols[b] = tmp;
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (j > 0) writeChar(' ');
            writeInt(rows[i] * M + cols[j] + 1);
        }
        writeChar('\n');
    }

    flushOutput();
    free(rows);
    free(cols);
    return 0;
}
